/* ─────────────────────────────────────────────────────────────
 * Landing photo essay — the plates
 *   .landing-band     : full-bleed photographic band under the hero
 *   .landing-plate    : one alternating image/text spread
 *   [data-reveal]     : scroll-triggered fade + rise
 *
 * The reveal's hidden start state is scoped to [data-reveal-ready],
 * which JS sets. Without JS nothing is ever hidden, so the SSR'd
 * page reads exactly as it did before — and stays crawlable.
 * ───────────────────────────────────────────────────────────── */

/* Full-bleed out of .landing-shell's centred column. .landing-page
   already sets `overflow: clip`, so 100vw can't raise a scrollbar. */
.landing-band {
  position: relative;
  width: 100vw;
  margin-inline: calc(50% - 50vw);
  overflow: hidden;
  aspect-ratio: 16 / 9;
  background: var(--color-paper-2);
  border-block: 1px solid color-mix(in srgb, var(--color-ink) 12%, transparent);
}
@media (min-width: 768px) {
  .landing-band {
    aspect-ratio: 3 / 1;
  }
}
.landing-band img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transform-origin: 50% 55%;
}
/* Slow ken-burns drift. Off-screen animations are throttled by the
   browser, so this costs nothing until the band is in view. */
@keyframes landing-band-drift {
  from {
    transform: scale(1);
  }
  to {
    transform: scale(1.06);
  }
}
.landing-band img {
  animation: landing-band-drift 20s ease-in-out infinite alternate;
}
/* Ink wash so the photograph sits inside the paper palette rather
   than punching a hole through it. */
.landing-band::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(
    180deg,
    color-mix(in srgb, var(--color-paper) 55%, transparent) 0%,
    transparent 22%,
    transparent 78%,
    color-mix(in srgb, var(--color-paper) 65%, transparent) 100%
  );
}

/* ── One spread ── */
.landing-plate {
  display: grid;
  gap: 1.75rem;
  align-items: center;
}
@media (min-width: 768px) {
  .landing-plate {
    grid-template-columns: 1fr 1fr;
    gap: 3.5rem;
  }
  /* Odd plates keep the photograph left; even plates flip it right. */
  .landing-plate--right .landing-plate__figure {
    order: 2;
  }
}

.landing-plate__figure {
  margin: 0;
  padding: 0.5rem;
  background: var(--color-paper-soft);
  border: 1px solid color-mix(in srgb, var(--color-ink) 16%, transparent);
  border-radius: 3px;
  box-shadow:
    0 1px 0 color-mix(in srgb, var(--emboss) 70%, transparent) inset,
    0 30px 60px -38px color-mix(in srgb, var(--shade) 45%, transparent);
  transform: rotate(-0.45deg);
  transition:
    transform 0.3s cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 0.3s ease;
}
.landing-plate--right .landing-plate__figure {
  transform: rotate(0.45deg);
}
.landing-plate__figure:hover,
.landing-plate--right .landing-plate__figure:hover {
  transform: translateY(-2px) rotate(0deg);
  box-shadow:
    0 1px 0 color-mix(in srgb, var(--emboss) 70%, transparent) inset,
    0 40px 72px -36px color-mix(in srgb, var(--shade) 55%, transparent);
}

.landing-plate__frame {
  overflow: hidden;
  border-radius: 2px;
  aspect-ratio: 3 / 2;
  background: var(--color-paper-3);
}
.landing-plate__frame--portrait {
  aspect-ratio: 4 / 5;
}
.landing-plate__frame img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.landing-plate__label {
  font-family: var(--font-typewriter);
  font-size: 0.68rem;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--color-vermilion);
}

/* ── Scroll reveal ── */
[data-reveal-ready] [data-reveal] {
  opacity: 0;
  transform: translateY(16px);
  transition:
    opacity 0.7s cubic-bezier(0.22, 1, 0.36, 1),
    transform 0.7s cubic-bezier(0.22, 1, 0.36, 1);
  transition-delay: var(--reveal-delay, 0ms);
}
[data-reveal-ready] [data-reveal].is-revealed {
  opacity: 1;
  transform: none;
}

/* ── Scroll-linked parallax on the plates ──
   Pure CSS via scroll-driven animations: no rAF listener, nothing
   added to Qwik's resumable page. Firefox has no support yet and
   simply gets a clean static photograph. */
@keyframes landing-plate-parallax {
  from {
    transform: translateY(-12px) scale(1.08);
  }
  to {
    transform: translateY(12px) scale(1.08);
  }
}
@supports (animation-timeline: view()) {
  @media (prefers-reduced-motion: no-preference) {
    .landing-plate__frame img {
      animation: landing-plate-parallax linear both;
      animation-timeline: view();
      animation-range: cover 0% cover 100%;
    }
  }
}

/* ── Theme fit ── */
/* Nightpress: knock the photographs back so they don't glare
   against the #191714 page. */
[data-theme="nightpress"] .landing-plate__frame img,
[data-theme="nightpress"] .landing-band img {
  filter: brightness(0.9) contrast(1.02);
}
/* Broadsheet is deliberately untinted, so drop the paper wash. */
[data-theme="broadsheet"] .landing-band::after {
  display: none;
}

@media (prefers-reduced-motion: reduce) {
  .landing-band img {
    animation: none;
  }
  .landing-plate__figure,
  .landing-plate--right .landing-plate__figure {
    transition: none;
  }
  .landing-plate__figure:hover,
  .landing-plate--right .landing-plate__figure:hover {
    transform: rotate(0deg);
  }
  /* Never hide content when motion is unwelcome. */
  [data-reveal-ready] [data-reveal] {
    opacity: 1;
    transform: none;
    transition: none;
  }
}
