const HERO_TITLE = "Draft with a room full of editors.";

/**
 * The headline types itself in. Split it into words, and each word into
 * characters: the word is what wraps, so a line break never lands mid-word,
 * and the spaces stay real text nodes so the h1 still copies as plain prose.
 * `index` counts across the whole headline — spaces included — so the reveal
 * keeps one steady keystroke rhythm rather than speeding up between words.
 */
const typedHeadline = (() => {
  let index = 0;
  const words = HERO_TITLE.split(" ").map((word) => {
    const chars = [...word].map((char) => ({ char, index: index++ }));
    index += 1; // the space that follows this word
    return chars;
  });
  return { words, length: index };
})();

