      header: g("header"), hero: g(".landing-hero"), inner: g(".landing-hero__inner"),
      mast: g(".landing-masthead") });
  };
  const iv = setInterval(snap, 60);
  setTimeout(() => clearInterval(iv), 3000);
});
await page.goto("http://localhost:5173/", { waitUntil: "load" });
await page.waitForTimeout(3200);
